typedef float rational_t;

class vector3d
{
public:
  float x;
  float y;
  float z;

  vector3d() {}
  vector3d(float _x, float _y, float _z) : x(_x), y(_y), z(_z) {}
  vector3d(const vector3d& v) : x(v.x), y(v.y), z(v.z) {}
  vector3d& operator=(const vector3d& v)
  {
    x = v.x;
    y = v.y;
    z = v.z;
    return *this;
  }
};

inline vector3d operator-(const vector3d& a, const vector3d& b)
{
  return vector3d(a.x-b.x, a.y-b.y, a.z-b.z);
}

inline rational_t dot(const vector3d& a, const vector3d& b)
{
  return a.x*b.x+a.y*b.y+a.z*b.z;
}

class po
{
public:
  vector3d slow_xform(const vector3d& v) const;
};

class entity
{
public:
  void get_velocity(vector3d* v) const;
};

class capsule
{
public:
  vector3d base;
  vector3d end;
  rational_t radius;
};

class collision_geometry
{
public:
  virtual ~collision_geometry();
  virtual collision_geometry* make_instance(entity*) const = 0;
  virtual void xform(const po&);
  virtual void apply_radius_scale(rational_t);
  virtual void split_xform(const po&, const po&, int);

protected:
  entity* owner;
  bool valid;
};

class collision_capsule : public collision_geometry
{
public:
  capsule rel_cap;
  capsule abs_cap;
  vector3d lag_point;

  void split_xform(po const & po_1, po const & po_2, int second_po_start_idx);
};

void collision_capsule::split_xform(po const & po_1, po const & po_2, int second_po_start_idx)
{
  // Note:  po_2 is last frame's po.
  collision_geometry::xform(po_2);
  vector3d vel;
  owner->get_velocity(&vel);
  abs_cap.base = po_2.slow_xform(rel_cap.base);
  abs_cap.end = po_2.slow_xform(rel_cap.end);
  abs_cap.radius = rel_cap.radius;
  rational_t a = dot(abs_cap.end-abs_cap.base,vel);
  if (a>0)
  {
    abs_cap.end = po_1.slow_xform(rel_cap.end);
    lag_point = abs_cap.base;
  }
  else
  {
    abs_cap.base = po_1.slow_xform(rel_cap.base);
    lag_point = abs_cap.end;
  }
}
